use std::fs;
use std::io;
use std::path::{Path, PathBuf};

/// Default location of the API key, relative to the process working directory.
pub const DEFAULT_API_KEY_PATH: &str = "secrets/api.key";

/// Errors that can occur while loading the API key.
#[derive(Debug)]
pub enum AuthError {
    /// The key file could not be read.
    Io(io::Error),
    /// The key file was readable but contained no key material.
    EmptyKey { path: PathBuf },
}

impl std::fmt::Display for AuthError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        // Note: never include the key value itself in error output.
        match self {
            AuthError::Io(e) => write!(f, "failed to read API key: {e}"),
            AuthError::EmptyKey { path } => {
                write!(f, "API key file {} is empty", path.display())
            }
        }
    }
}

impl std::error::Error for AuthError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            AuthError::Io(e) => Some(e),
            AuthError::EmptyKey { .. } => None,
        }
    }
}

impl From<io::Error> for AuthError {
    fn from(e: io::Error) -> Self {
        AuthError::Io(e)
    }
}

/// Reads the API key from `path`, trimming surrounding whitespace
/// (including the trailing newline most editors add).
pub fn load_api_key_from(path: impl AsRef<Path>) -> Result<String, AuthError> {
    let path = path.as_ref();
    let raw = fs::read_to_string(path)?;
    let key = raw.trim().to_owned();

    if key.is_empty() {
        return Err(AuthError::EmptyKey {
            path: path.to_path_buf(),
        });
    }

    Ok(key)
}

/// Reads the API key from the default location, [`DEFAULT_API_KEY_PATH`].
pub fn load_api_key() -> Result<String, AuthError> {
    load_api_key_from(DEFAULT_API_KEY_PATH)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::time::{SystemTime, UNIX_EPOCH};

    /// Writes `contents` to a unique temp file and returns its path.
    fn temp_key_file(contents: &str) -> PathBuf {
        let nanos = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let path = std::env::temp_dir().join(format!(
            "auth_test_{}_{}.key",
            std::process::id(),
            nanos
        ));
        fs::write(&path, contents).unwrap();
        path
    }

    #[test]
    fn reads_key_and_trims_trailing_newline() {
        let path = temp_key_file("super-secret-key\n");
        let key = load_api_key_from(&path).unwrap();
        fs::remove_file(&path).ok();
        assert_eq!(key, "super-secret-key");
    }

    #[test]
    fn rejects_empty_key_file() {
        let path = temp_key_file("  \n\n");
        let err = load_api_key_from(&path).unwrap_err();
        fs::remove_file(&path).ok();
        assert!(matches!(err, AuthError::EmptyKey { .. }));
    }

    #[test]
    fn missing_file_is_an_io_error() {
        let err = load_api_key_from("secrets/does-not-exist.key").unwrap_err();
        assert!(matches!(err, AuthError::Io(_)));
    }
}
